#!/usr/bin/env python3
"""Source builder for the original Cinderfall wasteland town.
The embedded zlib-compressed source can be unpacked with: 
python3 -c "import base64,zlib;from pathlib import Path;from scripts.apply_cinderfall_map import EMBEDDED;Path('cinderfall_readable.py').write_bytes(zlib.decompress(base64.b64decode(EMBEDDED)))"
The standalone readable source is also available in the ChatGPT conversation.
"""
import base64, zlib
EMBEDDED = ""
if __name__ == "__main__":
    exec(compile(zlib.decompress(base64.b64decode(EMBEDDED)), "cinderfall_map_builder.py", "exec"), {"__name__": "__main__"})
